/// <summary>
/// Extension class for PriceDiscTable data source
/// </summary>
[ExtensionOf(formDataSourceStr(PriceDiscTable, PriceDiscTable))]
internal final class AVARUMPriceDiscTable_PriceDiscTableDS_Extension
{
}

Method.Source:
/// <summary>
/// Extension of executeQuery method
/// </summary>
public void executeQuery()
{
    FormRun formRun;
    FormCheckBoxControl showAutoGeneratedPricesCheckBox;
    QueryBuildDataSource qbds;
    QueryBuildRange qbr;

    formRun = this.formRun();
    showAutoGeneratedPricesCheckBox = formRun.design().controlName(formControlStr(PriceDiscTable, AVARUMShowAutoGeneratedPrices)) as FormCheckBoxControl;

    qbds = this.query().dataSourceTable(tableNum(PriceDiscTable));
    qbds.clearRange(fieldNum(PriceDiscTable, AVARUMIsPriceAutoGenerated));

    if (!showAutoGeneratedPricesCheckBox.checked())
    {
        qbr = SysQuery::findOrCreateRange(qbds, fieldNum(PriceDiscTable, AVARUMIsPriceAutoGenerated));
        qbr.value(queryValue(showAutoGeneratedPricesCheckBox.checked() ? NoYes::Yes : NoYes::No));
    }

    next executeQuery();
}
